use glam::DVec3;use ingetrazo_core::{scene::Scene,georef::{GeoPath,geopath_to_geometry}};use serde_json::{Value,json};
fn point(p:&Value)->DVec3{DVec3::new(p[0].as_f64().unwrap(),p[1].as_f64().unwrap(),p[2].as_f64().unwrap())}
fn main(){let a:Vec<_>=std::env::args().collect();let cases:Value=serde_json::from_slice(&std::fs::read(&a[1]).unwrap()).unwrap();let mut results=vec![];for c in cases.as_array().unwrap(){let mut scene=Scene::new();for f in c["faces"].as_array().unwrap(){let ids=f["vertices"].as_array().unwrap().iter().map(|p|scene.mesh.add_vertex(point(p))).collect();let i=scene.mesh.add_face(ids,vec![]).unwrap();scene.mesh.faces[i].attrs=serde_json::from_value(f["attrs"].clone()).unwrap();}for e in c["edges"].as_array().unwrap(){let a=scene.mesh.add_vertex(point(&e[0]));let b=scene.mesh.add_vertex(point(&e[1]));scene.mesh.add_edge(a,b);}for p in c["paths"].as_array().unwrap(){scene.geo_paths.push(GeoPath::new(p["points"].as_array().unwrap().iter().map(point).collect(),p["closed"].as_bool().unwrap(),"reference"));}let ids:Vec<_>=(0..scene.geo_paths.len()).collect();let before=scene.clone();assert!(geopath_to_geometry(&mut scene,&[999]).is_err());assert_eq!(before,scene);let added=geopath_to_geometry(&mut scene,&ids).unwrap();results.push(json!({"added":added,"paths_remaining":scene.geo_paths.len(),"faces":scene.mesh.faces.iter().map(|f|json!({"vertices":f.vertices.iter().map(|&v|scene.mesh.vertices[v].position.to_array()).collect::<Vec<_>>(),"holes":f.holes.iter().map(|h|h.iter().map(|&v|scene.mesh.vertices[v].position.to_array()).collect::<Vec<_>>()).collect::<Vec<_>>(),"attrs":f.attrs})).collect::<Vec<_>>(),"edges":scene.mesh.edges.iter().map(|e|[scene.mesh.vertices[e.v0].position.to_array(),scene.mesh.vertices[e.v1].position.to_array()]).collect::<Vec<_>>()}));}std::fs::write(&a[2],serde_json::to_vec(&results).unwrap()).unwrap();}
